<script setup lang="ts">import {computed} from "vue";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import StatCard from "@/components/zs/StatCard.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney} from "@/lib/money";import {setPageMeta} from "@/lib/page-meta";import type {Settlement} from "@/types/operations";setPageMeta("Payment Settlements","Map merchant gross receipts, fees and net deposits.");const c=useCompanyStore(),s=useAsyncData(()=>operationsRepository.settlements(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),rows=computed(()=>s.data.value??[]);const columns:Column[]=[{key:"provider",header:"Provider"},{key:"reference",header:"Settlement"},{key:"date",header:"Date"},{key:"gross",header:"Gross",align:"right",class:"num"},{key:"fees",header:"Fees",align:"right",class:"num"},{key:"net",header:"Net deposit",align:"right",class:"num"},{key:"bank",header:"Bank account"},{key:"status",header:"Status"}];</script><template><AppShell><PageHeader title="Payment Settlements" description="JazzCash, Easypaisa, Stripe and terminal deposit mapping"/><div class="mb-4 grid gap-3 sm:grid-cols-3"><StatCard label="Gross collected" :value="formatMoney(rows.reduce((a,x)=>a+x.gross,0))" tone="brand"/><StatCard label="Processing fees" :value="formatMoney(rows.reduce((a,x)=>a+x.fees,0))" tone="warning"/><StatCard label="Net deposits" :value="formatMoney(rows.reduce((a,x)=>a+x.net,0))" tone="success"/></div><Panel><DataTable :columns="columns" :rows="rows" :min-width="1050"><template #provider="{row}:{row:Settlement}"><span class="font-medium text-content">{{row.provider}}</span></template><template #reference="{row}">{{row.reference}}</template><template #date="{row}">{{row.date}}</template><template #gross="{row}">{{formatMoney(row.gross)}}</template><template #fees="{row}">{{formatMoney(row.fees)}}</template><template #net="{row}">{{formatMoney(row.net)}}</template><template #bank="{row}">{{row.bank_account}}</template><template #status="{row}"><StatusBadge :status="row.status"/></template></DataTable></Panel></AppShell></template>